// Funnel-Konfiguration aus Webhook-Daten extrahieren und validieren
const input = $input.first().json;

const config = {
  companyName: input.companyName || 'Mein Unternehmen',
  primaryColor: input.primaryColor || '#2563EB',
  secondaryColor: input.secondaryColor || '#1E40AF',
  accentColor: input.accentColor || '#F59E0B',
  headline: input.headline || 'Ihr kostenloses Angebot wartet',
  subheadline: input.subheadline || 'Tragen Sie Ihre Daten ein und erhalten Sie sofort Zugang.',
  ctaText: input.ctaText || 'Jetzt herunterladen',
  logoUrl: input.logoUrl || '',
  downloadFileName: input.downloadFileName || 'download.pdf',
  downloadFileUrl: input.downloadFileUrl || '',
  customerEmail: input.customerEmail || '',
  formFields: input.formFields || [
    { name: 'firstName', label: 'Vorname', type: 'text', required: true },
    { name: 'lastName', label: 'Nachname', type: 'text', required: true },
    { name: 'email', label: 'E-Mail', type: 'email', required: true },
    { name: 'phone', label: 'Telefon', type: 'tel', required: false },
    { name: 'company', label: 'Unternehmen', type: 'text', required: false }
  ],
  benefits: input.benefits || [
    'Sofortiger Zugang zum Download',
    'Kostenlos und unverbindlich',
    'Expertenwissen kompakt zusammengefasst'
  ],
  privacyUrl: input.privacyUrl || '#datenschutz',
  thankYouHeadline: input.thankYouHeadline || 'Vielen Dank!',
  thankYouText: input.thankYouText || 'Ihr Download steht bereit. Prüfen Sie auch Ihren Posteingang.',
  // Metriken-basierte Anpassungen
  metricsMode: input.metricsMode || 'standard',
  conversionGoal: input.conversionGoal || 0.05,
  targetAudience: input.targetAudience || 'general'
};

// Metriken-basierte Layout-Optimierung
if (config.conversionGoal > 0.08) {
  config.layoutMode = 'aggressive';
  config.showUrgency = true;
  config.showSocialProof = true;
} else if (config.conversionGoal > 0.04) {
  config.layoutMode = 'balanced';
  config.showUrgency = false;
  config.showSocialProof = true;
} else {
  config.layoutMode = 'minimal';
  config.showUrgency = false;
  config.showSocialProof = false;
}

return [{ json: config }];

const config = $input.first().json;

// Formular-Felder generieren
const formFieldsHtml = config.formFields.map(field => {
  const required = field.required ? 'required' : '';
  const requiredStar = field.required ? '<span class="required">*</span>' : '';
  return `
    <div class="form-group">
      <label for="${field.name}">${field.label}${requiredStar}</label>
      <input
        type="${field.type}"
        id="${field.name}"
        name="${field.name}"
        placeholder="${field.placeholder || ''}"
        ${required}
        class="form-input"
      />
    </div>`;
}).join('\n');

// Benefits generieren
const benefitsHtml = config.benefits.map(b =>
  `<li><svg class="check-icon" viewBox="0 0 20 20" fill="currentColor"><path fill-rule="evenodd" d="M16.707 5.293a1 1 0 010 1.414l-8 8a1 1 0 01-1.414 0l-4-4a1 1 0 011.414-1.414L8 12.586l7.293-7.293a1 1 0 011.414 0z" clip-rule="evenodd"/></svg>${b}</li>`
).join('\n');

// Urgency-Banner
const urgencyHtml = config.showUrgency ? `
  <div class="urgency-banner">
    <span class="urgency-icon">⏰</span>
    <span>Nur noch für kurze Zeit verfügbar!</span>
  </div>` : '';

// Social Proof
const socialProofHtml = config.showSocialProof ? `
  <div class="social-proof">
    <div class="social-proof-item">
      <span class="social-number">2.500+</span>
      <span class="social-label">Downloads</span>
    </div>
    <div class="social-proof-item">
      <span class="social-number">4.8/5</span>
      <span class="social-label">Bewertung</span>
    </div>
    <div class="social-proof-item">
      <span class="social-number">98%</span>
      <span class="social-label">Zufriedenheit</span>
    </div>
  </div>` : '';

// Logo
const logoHtml = config.logoUrl
  ? `<img src="${config.logoUrl}" alt="${config.companyName}" class="logo" />`
  : `<h2 class="logo-text">${config.companyName}</h2>`;

// Landing Page HTML
const landingPageHtml = `<!DOCTYPE html>
<html lang="de">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>${config.headline} - ${config.companyName}</title>
  <link rel="preconnect" href="https://fonts.googleapis.com">
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    :root {
      --primary: ${config.primaryColor};
      --secondary: ${config.secondaryColor};
      --accent: ${config.accentColor};
      --text: #1F2937;
      --text-light: #6B7280;
      --bg: #F9FAFB;
      --white: #FFFFFF;
      --border: #E5E7EB;
      --radius: 12px;
    }
    body {
      font-family: "Inter", -apple-system, sans-serif;
      background: var(--bg);
      color: var(--text);
      line-height: 1.6;
      min-height: 100vh;
    }
    .container {
      max-width: 1100px;
      margin: 0 auto;
      padding: 2rem 1.5rem;
    }
    .header {
      text-align: center;
      padding: 1.5rem 0;
    }
    .logo { max-height: 48px; margin-bottom: 0.5rem; }
    .logo-text {
      font-size: 1.25rem;
      font-weight: 700;
      color: var(--primary);
    }
    .urgency-banner {
      background: linear-gradient(135deg, #FEF3C7, #FDE68A);
      border: 1px solid #F59E0B;
      border-radius: var(--radius);
      padding: 0.75rem 1.5rem;
      text-align: center;
      font-weight: 600;
      margin-bottom: 2rem;
      display: flex;
      align-items: center;
      justify-content: center;
      gap: 0.5rem;
    }
    .hero {
      display: grid;
      grid-template-columns: 1fr 1fr;
      gap: 3rem;
      align-items: start;
      margin-top: 1rem;
    }
    @media (max-width: 768px) {
      .hero { grid-template-columns: 1fr; gap: 2rem; }
    }
    .hero-content h1 {
      font-size: 2.25rem;
      font-weight: 700;
      line-height: 1.2;
      margin-bottom: 1rem;
      color: var(--text);
    }
    .hero-content p {
      font-size: 1.125rem;
      color: var(--text-light);
      margin-bottom: 1.5rem;
    }
    .benefits-list {
      list-style: none;
      display: flex;
      flex-direction: column;
      gap: 0.75rem;
    }
    .benefits-list li {
      display: flex;
      align-items: center;
      gap: 0.75rem;
      font-size: 1rem;
      color: var(--text);
    }
    .check-icon {
      width: 20px;
      height: 20px;
      color: #10B981;
      flex-shrink: 0;
    }
    .social-proof {
      display: flex;
      gap: 2rem;
      margin-top: 2rem;
      padding-top: 1.5rem;
      border-top: 1px solid var(--border);
    }
    .social-proof-item { text-align: center; }
    .social-number {
      display: block;
      font-size: 1.5rem;
      font-weight: 700;
      color: var(--primary);
    }
    .social-label {
      font-size: 0.813rem;
      color: var(--text-light);
    }
    .form-card {
      background: var(--white);
      border-radius: var(--radius);
      padding: 2rem;
      box-shadow: 0 4px 24px rgba(0,0,0,0.08);
      border: 1px solid var(--border);
    }
    .form-card h3 {
      font-size: 1.25rem;
      margin-bottom: 0.25rem;
    }
    .form-card .form-subtitle {
      color: var(--text-light);
      font-size: 0.875rem;
      margin-bottom: 1.5rem;
    }
    .form-group {
      margin-bottom: 1rem;
    }
    .form-group label {
      display: block;
      font-size: 0.875rem;
      font-weight: 500;
      margin-bottom: 0.375rem;
      color: var(--text);
    }
    .required { color: #EF4444; margin-left: 2px; }
    .form-input {
      width: 100%;
      padding: 0.625rem 0.875rem;
      border: 1px solid var(--border);
      border-radius: 8px;
      font-size: 0.938rem;
      font-family: inherit;
      transition: border-color 0.2s, box-shadow 0.2s;
      outline: none;
    }
    .form-input:focus {
      border-color: var(--primary);
      box-shadow: 0 0 0 3px rgba(37, 99, 235, 0.1);
    }
    .privacy-check {
      display: flex;
      align-items: flex-start;
      gap: 0.5rem;
      margin: 1.25rem 0;
      font-size: 0.813rem;
      color: var(--text-light);
    }
    .privacy-check input { margin-top: 2px; }
    .privacy-check a { color: var(--primary); }
    .submit-btn {
      width: 100%;
      padding: 0.875rem;
      background: linear-gradient(135deg, var(--primary), var(--secondary));
      color: white;
      border: none;
      border-radius: 8px;
      font-size: 1.063rem;
      font-weight: 600;
      cursor: pointer;
      transition: transform 0.15s, box-shadow 0.15s;
      font-family: inherit;
    }
    .submit-btn:hover {
      transform: translateY(-1px);
      box-shadow: 0 4px 12px rgba(37, 99, 235, 0.3);
    }
    .submit-btn:disabled {
      opacity: 0.6;
      cursor: not-allowed;
      transform: none;
    }
    .form-success {
      display: none;
      text-align: center;
      padding: 2rem 1rem;
    }
    .form-success.visible { display: block; }
    .form-success .success-icon {
      width: 64px;
      height: 64px;
      background: #D1FAE5;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      margin: 0 auto 1rem;
      font-size: 2rem;
    }
    .footer {
      text-align: center;
      padding: 2rem 0;
      color: var(--text-light);
      font-size: 0.813rem;
    }
    .footer a { color: var(--primary); text-decoration: none; }
    .spinner {
      display: inline-block;
      width: 18px;
      height: 18px;
      border: 2px solid rgba(255,255,255,0.3);
      border-top-color: white;
      border-radius: 50%;
      animation: spin 0.6s linear infinite;
      vertical-align: middle;
      margin-right: 0.5rem;
    }
    @keyframes spin { to { transform: rotate(360deg); } }
  </style>
</head>
<body>
  <div class="container">
    <div class="header">
      ${logoHtml}
    </div>

    ${urgencyHtml}

    <div class="hero">
      <div class="hero-content">
        <h1>${config.headline}</h1>
        <p>${config.subheadline}</p>
        <ul class="benefits-list">
          ${benefitsHtml}
        </ul>
        ${socialProofHtml}
      </div>

      <div class="form-card">
        <h3>Kostenlos erhalten</h3>
        <p class="form-subtitle">Füllen Sie das Formular aus und erhalten Sie sofort Zugang.</p>

        <form id="leadForm" novalidate>
          ${formFieldsHtml}

          <div class="privacy-check">
            <input type="checkbox" id="privacy" name="privacy" required />
            <label for="privacy">
              Ich stimme der Verarbeitung meiner Daten gemäß der
              <a href="${config.privacyUrl}" target="_blank">Datenschutzerklärung</a> zu.
            </label>
          </div>

          <button type="submit" class="submit-btn" id="submitBtn">
            ${config.ctaText}
          </button>
        </form>

        <div class="form-success" id="formSuccess">
          <div class="success-icon">✓</div>
          <h3>${config.thankYouHeadline}</h3>
          <p style="margin-top: 0.5rem; color: var(--text-light);">${config.thankYouText}</p>
          <a href="#" id="downloadLink" class="submit-btn" style="display:inline-block; margin-top:1.5rem; text-decoration:none; text-align:center;">
            Jetzt herunterladen
          </a>
        </div>
      </div>
    </div>

    <div class="footer">
      <p>&copy; ${new Date().getFullYear()} ${config.companyName}. Alle Rechte vorbehalten.</p>
      <p><a href="${config.privacyUrl}">Datenschutz</a> · <a href="#impressum">Impressum</a></p>
    </div>
  </div>

  <script>
    (function() {
      const WEBHOOK_URL = '{{LEAD_WEBHOOK_URL}}';
      const DOWNLOAD_URL = '${config.downloadFileUrl || '#'}';

      const form = document.getElementById('leadForm');
      const submitBtn = document.getElementById('submitBtn');
      const formSuccess = document.getElementById('formSuccess');
      const downloadLink = document.getElementById('downloadLink');

      downloadLink.href = DOWNLOAD_URL;

      // Tracking-Events
      function trackEvent(event) {
        if (typeof gtag === 'function') gtag('event', event);
        if (typeof fbq === 'function') fbq('track', event);
        console.log('[Funnel Event]', event);
      }

      trackEvent('page_view');

      // Erster Feld-Fokus tracken
      let formStarted = false;
      form.querySelectorAll('.form-input').forEach(input => {
        input.addEventListener('focus', () => {
          if (!formStarted) {
            formStarted = true;
            trackEvent('form_start');
          }
        });
      });

      form.addEventListener('submit', async (e) => {
        e.preventDefault();

        if (!document.getElementById('privacy').checked) {
          alert('Bitte stimmen Sie der Datenschutzerklärung zu.');
          return;
        }

        submitBtn.disabled = true;
        submitBtn.innerHTML = '<span class="spinner"></span>Wird gesendet...';

        const formData = new FormData(form);
        const data = {};
        formData.forEach((value, key) => { if (key !== 'privacy') data[key] = value; });
        data.submittedAt = new Date().toISOString();
        data.source = window.location.href;

        try {
          const response = await fetch(WEBHOOK_URL, {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify(data)
          });

          if (!response.ok) throw new Error('Übermittlung fehlgeschlagen');

          trackEvent('form_submit');
          form.style.display = 'none';
          document.querySelector('.form-card h3').style.display = 'none';
          document.querySelector('.form-subtitle').style.display = 'none';
          formSuccess.classList.add('visible');
        } catch (err) {
          alert('Es gab einen Fehler. Bitte versuchen Sie es erneut.');
          submitBtn.disabled = false;
          submitBtn.textContent = '${config.ctaText}';
        }
      });

      downloadLink.addEventListener('click', () => trackEvent('download_click'));
    })();
  </script>
</body>
</html>`;

return [{ json: { ...config, landingPageHtml } }];

const config = $input.first().json;

const thankYouHtml = `<!DOCTYPE html>
<html lang="de">
<head>
  <meta charset="UTF-8">
  <meta name="viewport" content="width=device-width, initial-scale=1.0">
  <title>Vielen Dank - ${config.companyName}</title>
  <link href="https://fonts.googleapis.com/css2?family=Inter:wght@400;500;600;700&display=swap" rel="stylesheet">
  <style>
    *, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
    :root {
      --primary: ${config.primaryColor};
      --secondary: ${config.secondaryColor};
      --accent: ${config.accentColor};
    }
    body {
      font-family: "Inter", sans-serif;
      background: #F9FAFB;
      min-height: 100vh;
      display: flex;
      align-items: center;
      justify-content: center;
    }
    .card {
      background: white;
      border-radius: 16px;
      padding: 3rem;
      max-width: 520px;
      width: 90%;
      text-align: center;
      box-shadow: 0 4px 24px rgba(0,0,0,0.08);
    }
    .success-icon {
      width: 80px;
      height: 80px;
      background: #D1FAE5;
      border-radius: 50%;
      display: flex;
      align-items: center;
      justify-content: center;
      margin: 0 auto 1.5rem;
      font-size: 2.5rem;
    }
    h1 { font-size: 1.75rem; margin-bottom: 0.75rem; }
    p { color: #6B7280; line-height: 1.6; margin-bottom: 1.5rem; }
    .download-btn {
      display: inline-block;
      padding: 0.875rem 2rem;
      background: linear-gradient(135deg, var(--primary), var(--secondary));
      color: white;
      border: none;
      border-radius: 8px;
      font-size: 1.063rem;
      font-weight: 600;
      text-decoration: none;
      transition: transform 0.15s;
    }
    .download-btn:hover { transform: translateY(-1px); }
    .back-link {
      display: block;
      margin-top: 1.5rem;
      color: #6B7280;
      font-size: 0.875rem;
      text-decoration: none;
    }
    .back-link:hover { color: var(--primary); }
  </style>
</head>
<body>
  <div class="card">
    <div class="success-icon">✓</div>
    <h1>${config.thankYouHeadline}</h1>
    <p>${config.thankYouText}</p>
    <a href="${config.downloadFileUrl || '#'}" class="download-btn" id="downloadBtn">
      ${config.downloadFileName || 'Datei'} herunterladen
    </a>
    <a href="/" class="back-link">← Zurück zur Startseite</a>
  </div>
  <script>
    document.getElementById('downloadBtn').addEventListener('click', function() {
      if (typeof gtag === 'function') gtag('event', 'download_click');
      if (typeof fbq === 'function') fbq('track', 'download_click');
    });
  </script>
</body>
</html>`;

return [{ json: { ...config, thankYouHtml } }];

